-- Say with a dynamic option list (engine Say takes the options as separate string arguments)
function PT45_Say(text, o)
	local n = getn(o)
	if n == 1 then Say(text, 1, o[1])
	elseif n == 2 then Say(text, 2, o[1], o[2])
	elseif n == 3 then Say(text, 3, o[1], o[2], o[3])
	elseif n == 4 then Say(text, 4, o[1], o[2], o[3], o[4])
	elseif n == 5 then Say(text, 5, o[1], o[2], o[3], o[4], o[5])
	elseif n == 6 then Say(text, 6, o[1], o[2], o[3], o[4], o[5], o[6])
	else Say(text, 7, o[1], o[2], o[3], o[4], o[5], o[6], o[7]) end
end

function PT45_NpcTalk(name, text)
	Talk(1, "", "<color=green>" .. name .. "<color>: " .. text)
end

