function pt_ask()
	local m = GetTask(PT45_T_MAIN)
	local st, pwd = PT45_Cmp()
	if (m ~= 31 and m ~= 32 and m ~= 37) or st ~= 4 then return end
	local k = PT45_IDX
	local mask, rot = PT45_Cmp2()
	local bit = 1
	local i = 1
	while i < k do bit = bit * 2 i = i + 1 end
	if mod(floor(mask / bit), 2) == 0 then mask = mask + bit end
	PT45_SetCmp2(mask, rot)
	local n = 0
	local b = 1
	i = 1
	while i <= 4 do
		if mod(floor(mask / b), 2) == 1 then n = n + 1 end
		b = b * 2
		i = i + 1
	end
	local code = PT45_DirName(PT45_Digit(pwd, k))
	if n >= 4 then
		PT45_SetCmp(5, pwd)
		PT45_SetMain(33)
		PT45_NoteMain(33, PT45_DirName(PT45_Digit(pwd, 1)), PT45_DirName(PT45_Digit(pwd, 2)), PT45_DirName(PT45_Digit(pwd, 3)), PT45_DirName(PT45_Digit(pwd, 4)))
		Msg2Player("§· cã ®ñ mËt m· 4 La Bµn! §Õn La Bµn trËn ph¸p xoay tõng La Bµn theo mËt m·.")
	else
		PT45_SetMain(32)
		PT45_NoteMain(32, PT45_PILLAR[k], n, PT45_PILLAR[k], code)
	end
	PT45_NpcTalk("Ph¸p trô (" .. PT45_PILLAR[k] .. ")", "MËt m· h­íng " .. PT45_PILLAR[k] .. " cña La Bµn lµ <color=yellow>" .. code .. "<color>.")
end

