function PT45_Rotate(d)
	local st, pwd = PT45_Cmp()
	if st ~= 5 then return end
	local k = PT45_IDX
	local mask, rot = PT45_Cmp2()
	local v = mod(PT45_RotDigit(rot, k) + d, 8)
	rot = PT45_RotSet(rot, k, v)
	PT45_SetCmp2(mask, rot)
	Msg2Player("La Bµn (" .. PT45_PILLAR[k] .. ") xoay vÒ h­íng <color=yellow>" .. PT45_DirName(v) .. "<color>.")
	local ok = 1
	local i = 1
	while i <= 4 do
		if PT45_RotDigit(rot, i) ~= PT45_Digit(pwd, i) then ok = nil end
		i = i + 1
	end
	if ok then
		PT45_SetCmp(6, pwd)
		PT45_SetMain(34)
		PT45_NoteMain(34)
		Msg2Player("La Bµn trËn ph¸p ®· ®­îc hãa gi¶i! Dïng <color=yellow>Gi¶i chó phï<color> trong trËn ph¸p ®Ó më Ph¸p trËn.")
	end
	P_laban()
end

